/**
 * One Modelo 036 tipo-de-actividad code.
 *
 * The value byte-equals the stored token, so a member compares, hashes, and
 * JSON-serialises identically to its string.
 *
 * Attributes: A01_ARRENDADORES_BIENES_INMUEBLES: Arrendadores de bienes
 * inmuebles. A02_GANADERIA_INDEPENDIENTE: Ganadería independiente. Subject to
 * IAE, yet art. 95.4 counts it among the actividades agrícolas o ganaderas
 * expressly (*Se entenderán incluidas ... a) La ganadería independiente*), so
 * it partitions with the `B` livestock code rather than against it.
 * A03_RESTO_EMPRESARIALES: Resto de actividades empresariales.
 * A04_ARTISTICAS_Y_DEPORTIVAS: Artísticas y deportivas — Sección Tercera of
 * the IAE tarifas, which art. 95.2.a) counts as rendimientos de actividades
 * profesionales alongside Sección Segunda. A05_PROFESIONALES: Profesionales —
 * Sección Segunda of the IAE tarifas. B01_AGRICOLA: Agrícola. B02_GANADERA:
 * Ganadera. B03_FORESTAL: Forestal. B04_PRODUCCION_DE_MEJILLON: Producción de
 * mejillón. B05_PESQUERA: Pesquera.
 */
export type TipoActividad =
  "A01" | "A02" | "A03" | "A04" | "A05" | "B01" | "B02" | "B03" | "B04" | "B05";

